def _env_orientation_smoothing():
    '''Read the head-orientation smoothing factor from XRSIM_HEAD_SMOOTHING.

    Lets the smoothing strength be tuned per session without a rebuild. Falls
    back to the default and clamps to (0.05, 1.0] so a stray value can neither
    freeze the pose nor exceed "no smoothing".
    '''
    raw = os.environ.get('XRSIM_HEAD_SMOOTHING')
    if not raw:
        return _DEFAULT_ORIENTATION_SMOOTHING
    
    try:
        value = float(raw)
        return max(0.05, min(1, value))
    except ValueError:
        logger.warning('Ignoring non-numeric XRSIM_HEAD_SMOOTHING=%r', raw)
        return _DEFAULT_ORIENTATION_SMOOTHING



